//! The surface Kotlin and Swift see, generated by UniFFI.
//!
//! Nothing here holds logic. It owns a tokio runtime, converts between the core's
//! types and plain records, and forwards events to the app. The names carry a
//! `Tandem` prefix so they never collide with the app's own types.

use std::sync::{Arc, Once};

use tokio::runtime::Runtime;
use tokio::sync::broadcast::error::RecvError;

use crate::engine::{DeviceInfo, Engine, EngineConfig};
use crate::events::Event;
use crate::ids::{DeviceId, Platform};
use crate::net::Route;
use crate::platform::FileStore;
use crate::proto::{
    Battery, CallActionKind, CallMsg, CallState, HotspotMsg, InputMsg, MediaKey, NetKind, NetworkStatus,
    NotifButton, NotificationAction, NotificationMsg, ShareOrigin, Status,
};
use crate::store::{DeviceSettings, SecretStore};
use crate::transfer::OutgoingFile;

#[derive(Debug, thiserror::Error, uniffi::Error)]
pub enum TandemError {
    #[error("{reason}")]
    Failed { reason: String },
    #[error("not connected to that device")]
    NotConnected,
    #[error("that device is not part of your circle")]
    NotTrusted,
    #[error("{reason}")]
    Pairing { reason: String },
}

impl From<crate::Error> for TandemError {
    fn from(err: crate::Error) -> Self {
        match err {
            crate::Error::NotConnected => TandemError::NotConnected,
            crate::Error::NotTrusted => TandemError::NotTrusted,
            crate::Error::Pairing(reason) => TandemError::Pairing { reason },
            other => TandemError::Failed { reason: other.to_string() },
        }
    }
}

// ---- Things the app implements ----------------------------------------------------

/// Receives everything the core reports. Called on a runtime thread, so it must not
/// block: post the event to the UI thread and return.
#[uniffi::export(foreign)]
pub trait TandemEventSink: Send + Sync {
    fn on_event(&self, event: TandemEvent);
}

/// Where the identity key is kept. Android wraps it with the Keystore, macOS uses the
/// Keychain.
#[uniffi::export(foreign)]
pub trait TandemVault: Send + Sync {
    /// `None` only when nothing was stored yet. Throw when the store cannot be read, so
    /// the engine stops instead of quietly making a new identity and orphaning every
    /// pairing.
    fn load(&self) -> Result<Option<Vec<u8>>, TandemError>;
    fn save(&self, secret: Vec<u8>) -> Result<(), TandemError>;
}

/// Opening files to send and placing files that arrived.
#[uniffi::export(foreign)]
pub trait TandemFiles: Send + Sync {
    /// Returns a file descriptor the core takes ownership of. Detach it on the Kotlin
    /// side (`ParcelFileDescriptor.detachFd`) so nothing else closes it.
    fn open_read(&self, source: String) -> Result<i32, TandemError>;
    /// Moves a finished download out of the private temp file and returns where it is.
    fn store_download(&self, temp_path: String, name: String, mime: String) -> Result<String, TandemError>;
}

struct VaultAdapter(Arc<dyn TandemVault>);

impl SecretStore for VaultAdapter {
    fn load(&self) -> crate::Result<Option<Vec<u8>>> {
        self.0.load().map_err(|e| crate::Error::Crypto(format!("the key store could not be read: {e}")))
    }

    fn save(&self, secret: &[u8]) -> crate::Result<()> {
        self.0
            .save(secret.to_vec())
            .map_err(|e| crate::Error::Crypto(format!("the key store could not be written: {e}")))
    }
}

struct FilesAdapter(Arc<dyn TandemFiles>);

impl FileStore for FilesAdapter {
    fn open_read(&self, source: &str) -> std::io::Result<std::fs::File> {
        use std::os::fd::FromRawFd;
        let fd = self
            .0
            .open_read(source.to_string())
            .map_err(|e| std::io::Error::other(e.to_string()))?;
        // The app detached the descriptor, so the file is ours to close.
        Ok(unsafe { std::fs::File::from_raw_fd(fd) })
    }

    fn store_download(&self, temp: &std::path::Path, name: &str, mime: &str) -> std::io::Result<String> {
        self.0
            .store_download(temp.to_string_lossy().into_owned(), name.to_string(), mime.to_string())
            .map_err(|e| std::io::Error::other(e.to_string()))
    }
}

