#[derive(Clone, Debug, uniffi::Record)]
pub struct TandemNotification {
    pub key: String,
    pub app_id: String,
    pub app_name: String,
    pub title: String,
    pub text: String,
    pub sub_text: Option<String>,
    pub ts: u64,
    pub ongoing: bool,
    pub silent: bool,
    pub buttons: Vec<TandemButton>,
    pub otp: Option<String>,
    pub progress_done: Option<u32>,
    pub progress_total: Option<u32>,
}

impl From<NotificationMsg> for TandemNotification {
    fn from(n: NotificationMsg) -> Self {
        TandemNotification {
            key: n.key,
            app_id: n.app_id,
            app_name: n.app_name,
            title: n.title,
            text: n.text,
            sub_text: n.sub_text,
            ts: n.ts,
            ongoing: n.ongoing,
            silent: n.silent,
            buttons: n
                .buttons
                .into_iter()
                .map(|b| TandemButton { id: b.id, title: b.title, is_reply: b.is_reply })
                .collect(),
            otp: n.otp,
            progress_done: n.progress.map(|p| p.0),
            progress_total: n.progress.map(|p| p.1),
        }
    }
}

impl From<TandemNotification> for NotificationMsg {
    fn from(n: TandemNotification) -> Self {
        NotificationMsg {
            key: n.key,
            app_id: n.app_id,
            app_name: n.app_name,
            title: n.title,
            text: n.text,
            sub_text: n.sub_text,
            ts: n.ts,
            ongoing: n.ongoing,
            silent: n.silent,
            buttons: n
                .buttons
                .into_iter()
                .map(|b| NotifButton { id: b.id, title: b.title, is_reply: b.is_reply })
                .collect(),
            otp: n.otp,
            progress: match (n.progress_done, n.progress_total) {
                (Some(done), Some(total)) => Some((done, total)),
                _ => None,
            },
        }
    }
}

