#[derive(Clone, Debug, uniffi::Enum)]
pub enum TandemEvent {
    DevicesChanged,
    Connected { id: String },
    Disconnected { id: String },
    Paired { id: String },
    CircleChanged,
    RemovedFromCircle,
    Clipboard { from: String, text: String, is_url: bool },
    ShareOffered { from: String, offer: u64, origin: TandemShareOrigin, items: Vec<TandemShareItem> },
    ShareText { from: String, text: String, is_url: bool, open: bool },
    Progress { offer: u64, index: u32, peer: String, incoming: bool, name: String, done: u64, total: u64 },
    Finished {
        offer: u64,
        index: u32,
        peer: String,
        incoming: bool,
        name: String,
        size: u64,
        location: Option<String>,
        error: Option<String>,
    },
    Notification { from: String, notification: TandemNotification },
    NotificationRemoved { from: String, key: String },
    NotificationAction { from: String, key: String, button: String, reply: Option<String>, dismiss: bool },
    AppIcon { from: String, app_id: String, png: Vec<u8> },
    Call { from: String, call: TandemCall },
    CallAction { from: String, id: String, action: TandemCallAction },
    Dial { from: String, number: String },
    Ring { from: String, on: bool },
    Input { from: String, input: TandemInput },
    Hotspot { from: String, hotspot: TandemHotspot },
}

impl From<Event> for TandemEvent {
    fn from(event: Event) -> Self {
        match event {
            Event::DevicesChanged => TandemEvent::DevicesChanged,
            Event::Connected { id } => TandemEvent::Connected { id: id.to_string() },
            Event::Disconnected { id } => TandemEvent::Disconnected { id: id.to_string() },
            Event::Paired { id } => TandemEvent::Paired { id: id.to_string() },
            Event::CircleChanged => TandemEvent::CircleChanged,
            Event::RemovedFromCircle => TandemEvent::RemovedFromCircle,
            Event::Clipboard { from, text, is_url } => TandemEvent::Clipboard { from: from.to_string(), text, is_url },
            Event::ShareOffered { from, offer } => TandemEvent::ShareOffered {
                from: from.to_string(),
                offer: offer.id,
                origin: offer.origin.into(),
                items: offer
                    .items
                    .into_iter()
                    .map(|i| TandemShareItem { name: i.name, size: i.size, mime: i.mime })
                    .collect(),
            },
            Event::ShareText { from, text, is_url, open } => {
                TandemEvent::ShareText { from: from.to_string(), text, is_url, open }
            }
            Event::Progress(p) => TandemEvent::Progress {
                offer: p.offer,
                index: p.index,
                peer: p.peer.to_string(),
                incoming: p.incoming,
                name: p.name,
                done: p.done,
                total: p.total,
            },
            Event::Finished(d) => TandemEvent::Finished {
                offer: d.offer,
                index: d.index,
                peer: d.peer.to_string(),
                incoming: d.incoming,
                name: d.name,
                size: d.size,
                location: d.location,
                error: d.error,
            },
            Event::Notification { from, notification } => {
                TandemEvent::Notification { from: from.to_string(), notification: notification.into() }
            }
            Event::NotificationRemoved { from, key } => TandemEvent::NotificationRemoved { from: from.to_string(), key },
            Event::NotificationAction { from, action } => TandemEvent::NotificationAction {
                from: from.to_string(),
                key: action.key,
                button: action.button,
                reply: action.reply,
                dismiss: action.dismiss,
            },
            Event::AppIcon { from, app_id, png } => TandemEvent::AppIcon { from: from.to_string(), app_id, png },
            Event::Call { from, call } => TandemEvent::Call {
                from: from.to_string(),
                call: TandemCall {
                    id: call.id,
                    state: call.state.into(),
                    incoming: call.incoming,
                    number: call.number,
                    name: call.name,
                    ts: call.ts,
                },
            },
            Event::CallAction { from, action } => {
                TandemEvent::CallAction { from: from.to_string(), id: action.id, action: action.action.into() }
            }
            Event::Dial { from, number } => TandemEvent::Dial { from: from.to_string(), number },
            Event::Ring { from, on } => TandemEvent::Ring { from: from.to_string(), on },
            Event::Input { from, input } => TandemEvent::Input { from: from.to_string(), input: input.into() },
            Event::Hotspot { from, hotspot } => TandemEvent::Hotspot { from: from.to_string(), hotspot: hotspot.into() },
        }
    }
}

// ---- Logging ----------------------------------------------------------------------

static LOGGING: Once = Once::new();

/// Routes the core's logs to the platform log (logcat on Android, the unified log on
/// Apple systems). Safe to call more than once.
#[uniffi::export]
pub fn tandem_init_logging(verbose: bool) {
    LOGGING.call_once(|| {
        let level = if verbose { log::LevelFilter::Debug } else { log::LevelFilter::Info };
        #[cfg(target_os = "android")]
        android_logger::init_once(android_logger::Config::default().with_max_level(level).with_tag("Tandem"));
        #[cfg(target_vendor = "apple")]
        {
            let _ = oslog::OsLogger::new("nl.markmaaktmedia.Tandem").level_filter(level).init();
        }
        #[cfg(not(any(target_os = "android", target_vendor = "apple")))]
        let _ = level;
    });
}

// ---- The engine -------------------------------------------------------------------

/// Owns the runtime and shuts it down without blocking, so dropping the engine from
/// any thread (including one that belongs to another runtime) is safe.
struct OwnedRuntime(Option<Runtime>);

impl std::ops::Deref for OwnedRuntime {
    type Target = Runtime;

    fn deref(&self) -> &Runtime {
        self.0.as_ref().expect("runtime is alive until drop")
    }
}

impl Drop for OwnedRuntime {
    fn drop(&mut self) {
        if let Some(runtime) = self.0.take() {
            runtime.shutdown_background();
        }
    }
}

#[derive(uniffi::Object)]
pub struct TandemEngine {
    runtime: OwnedRuntime,
    engine: Engine,
}

fn parse_ids(ids: &[String]) -> Result<Vec<DeviceId>, TandemError> {
    ids.iter()
        .map(|id| DeviceId::parse(id).map_err(TandemError::from))
        .collect()
}

fn ids_to_strings(ids: Vec<DeviceId>) -> Vec<String> {
    ids.into_iter().map(|id| id.to_string()).collect()
}

#[uniffi::export(async_runtime = "tokio")]
impl TandemEngine {
    /// Starts the engine. Call it from a background thread: it opens the socket and
    /// announces on the network.
    #[uniffi::constructor]
    pub fn start(
        config: TandemConfig,
        vault: Arc<dyn TandemVault>,
        files: Arc<dyn TandemFiles>,
        sink: Arc<dyn TandemEventSink>,
    ) -> Result<Arc<TandemEngine>, TandemError> {
        let runtime = tokio::runtime::Builder::new_multi_thread()
            .worker_threads(2)
            .thread_name("tandem")
            .enable_all()
            .build()
            .map_err(|e| TandemError::Failed { reason: e.to_string() })?;

        let mut cfg = EngineConfig::new(&config.data_dir, &config.device_name);
        cfg.platform = config.platform.into();
        cfg.model = config.model;
        cfg.app_version = config.app_version;
        cfg.port = config.port;
        cfg.enable_mdns = config.enable_mdns;
        cfg.caps = config.caps;
        if config.low_power {
            cfg.tuning.keep_alive = std::time::Duration::from_secs(25);
            cfg.tuning.idle_timeout = std::time::Duration::from_secs(70);
        }

        let engine = runtime
            .block_on(Engine::start(cfg, Arc::new(VaultAdapter(vault)), Arc::new(FilesAdapter(files))))
            .map_err(TandemError::from)?;

        let mut events = engine.subscribe();
        runtime.spawn(async move {
            loop {
                match events.recv().await {
                    Ok(event) => sink.on_event(event.into()),
                    Err(RecvError::Lagged(missed)) => {
                        tracing::warn!("the app fell behind by {missed} events");
                        sink.on_event(TandemEvent::DevicesChanged);
                    }
                    Err(RecvError::Closed) => break,
                }
            }
        });

        Ok(Arc::new(TandemEngine { runtime: OwnedRuntime(Some(runtime)), engine }))
    }

    pub fn id(&self) -> String {
        self.engine.id().to_string()
    }

    pub fn name(&self) -> String {
        self.engine.name()
    }

    pub fn port(&self) -> u16 {
        self.engine.port()
    }

    pub fn devices(&self) -> Vec<TandemDevice> {
        self.engine.devices().into_iter().map(Into::into).collect()
    }

    pub fn is_member(&self) -> bool {
        self.engine.is_member()
    }

    /// Call when Wi-Fi, mobile data or the VPN changed.
    pub fn network_changed(&self) {
        let _guard = self.runtime.enter();
        self.engine.network_changed();
    }

    pub fn create_pairing_offer(&self) -> Result<TandemPairingOffer, TandemError> {
        let offer = self.engine.create_pairing_offer()?;
        Ok(TandemPairingOffer { uri: offer.uri, expires_at_ms: offer.expires_at })
    }

    pub fn cancel_pairing_offer(&self) {
        self.engine.cancel_pairing_offer();
    }

    pub fn set_device_settings(
        &self,
        id: String,
        clipboard: bool,
        auto_accept: bool,
        notifications: bool,
    ) -> Result<(), TandemError> {
        let id = DeviceId::parse(&id)?;
        self.engine
            .set_device_settings(&id, DeviceSettings { clipboard, auto_accept, notifications })
            .map_err(Into::into)
    }

    pub fn accept_offer(&self, from: String, offer: u64) -> Result<(), TandemError> {
        let _guard = self.runtime.enter();
        self.engine.accept_offer(DeviceId::parse(&from)?, offer).map_err(Into::into)
    }

    pub fn is_connected(&self, id: String) -> bool {
        DeviceId::parse(&id).map(|id| self.engine.is_connected(&id)).unwrap_or(false)
    }

    /// Sends a pointer movement without waiting for delivery.
    pub fn send_pointer(&self, id: String, dx: i16, dy: i16) -> Result<(), TandemError> {
        let id = DeviceId::parse(&id)?;
        self.engine.send_datagram(&id, crate::session::pointer_datagram(dx, dy)).map_err(Into::into)
    }

    pub fn send_scroll(&self, id: String, dx: i16, dy: i16) -> Result<(), TandemError> {
        let id = DeviceId::parse(&id)?;
        self.engine.send_datagram(&id, crate::session::scroll_datagram(dx, dy)).map_err(Into::into)
    }

    pub async fn pair_with_uri(&self, uri: String) -> Result<String, TandemError> {
        let engine = self.engine.clone();
        let id = self
            .runtime
            .spawn(async move { engine.pair_with_uri(&uri).await })
            .await
            .map_err(join_error)??;
        Ok(id.to_string())
    }

    pub async fn remove_device(&self, id: String) -> Result<(), TandemError> {
        let id = DeviceId::parse(&id)?;
        let engine = self.engine.clone();
        self.runtime.spawn(async move { engine.remove_device(id).await }).await.map_err(join_error)??;
        Ok(())
    }

    pub async fn rename_self(&self, name: String) -> Result<(), TandemError> {
        let engine = self.engine.clone();
        self.runtime.spawn(async move { engine.rename_self(&name).await }).await.map_err(join_error)??;
        Ok(())
    }

    pub async fn send_files(
        &self,
        targets: Vec<String>,
        files: Vec<TandemOutgoingFile>,
        origin: TandemShareOrigin,
    ) -> Result<TandemSendReport, TandemError> {
        let targets = parse_ids(&targets)?;
        let files: Vec<OutgoingFile> = files
            .into_iter()
            .map(|f| OutgoingFile { source: f.source, name: f.name, size: f.size, mime: f.mime })
            .collect();
        let engine = self.engine.clone();
        let report = self
            .runtime
            .spawn(async move { engine.send_files(&targets, files, origin.into()).await })
            .await
            .map_err(join_error)??;
        Ok(TandemSendReport {
            offer: report.offer,
            sent_to: ids_to_strings(report.sent_to),
            offline: ids_to_strings(report.offline),
        })
    }

    pub async fn send_bytes(
        &self,
        targets: Vec<String>,
        name: String,
        mime: String,
        data: Vec<u8>,
        origin: TandemShareOrigin,
    ) -> Result<TandemSendReport, TandemError> {
        let targets = parse_ids(&targets)?;
        let engine = self.engine.clone();
        let report = self
            .runtime
            .spawn(async move { engine.send_bytes(&targets, &name, &mime, data, origin.into()).await })
            .await
            .map_err(join_error)??;
        Ok(TandemSendReport {
            offer: report.offer,
            sent_to: ids_to_strings(report.sent_to),
            offline: ids_to_strings(report.offline),
        })
    }

    pub async fn send_text(
        &self,
        targets: Vec<String>,
        text: String,
        is_url: bool,
        open: bool,
    ) -> Result<Vec<String>, TandemError> {
        let targets = parse_ids(&targets)?;
        let engine = self.engine.clone();
        let reached = self
            .runtime
            .spawn(async move { engine.send_text(&targets, &text, is_url, open).await })
            .await
            .map_err(join_error)?;
        Ok(ids_to_strings(reached))
    }

    pub async fn clipboard_changed(&self, text: String, is_url: bool) {
        let engine = self.engine.clone();
        let _ = self.runtime.spawn(async move { engine.clipboard_changed(&text, is_url).await }).await;
    }

    pub async fn send_clipboard(
        &self,
        targets: Vec<String>,
        text: String,
        is_url: bool,
    ) -> Result<Vec<String>, TandemError> {
        let targets = parse_ids(&targets)?;
        let engine = self.engine.clone();
        let reached = self
            .runtime
            .spawn(async move { engine.send_clipboard(&targets, &text, is_url).await })
            .await
            .map_err(join_error)?;
        Ok(ids_to_strings(reached))
    }

    pub async fn update_status(&self, status: TandemStatus) {
        let engine = self.engine.clone();
        let _ = self.runtime.spawn(async move { engine.update_status(status.into()).await }).await;
    }

    pub async fn send_notification(
        &self,
        targets: Vec<String>,
        notification: TandemNotification,
    ) -> Result<Vec<String>, TandemError> {
        self.send(targets, crate::proto::Msg::Notification(notification.into())).await
    }

    pub async fn remove_notification(&self, targets: Vec<String>, key: String) -> Result<Vec<String>, TandemError> {
        self.send(targets, crate::proto::Msg::NotificationRemoved { key }).await
    }

    pub async fn notification_action(
        &self,
        target: String,
        key: String,
        button: String,
        reply: Option<String>,
        dismiss: bool,
    ) -> Result<(), TandemError> {
        let msg = crate::proto::Msg::NotificationAction(NotificationAction { key, button, reply, dismiss });
        self.send(vec![target], msg).await.map(|_| ())
    }

    pub async fn send_app_icon(&self, targets: Vec<String>, app_id: String, png: Vec<u8>) -> Result<Vec<String>, TandemError> {
        self.send(targets, crate::proto::Msg::AppIcon { app_id, png: crate::proto::bytes(png) }).await
    }

    pub async fn send_call(&self, targets: Vec<String>, call: TandemCall) -> Result<Vec<String>, TandemError> {
        let msg = crate::proto::Msg::Call(CallMsg {
            id: call.id,
            state: call.state.into(),
            incoming: call.incoming,
            number: call.number,
            name: call.name,
            ts: call.ts,
        });
        self.send(targets, msg).await
    }

    pub async fn call_action(&self, target: String, id: String, action: TandemCallAction) -> Result<(), TandemError> {
        let msg = crate::proto::Msg::CallAction(crate::proto::CallAction { id, action: action.into() });
        self.send(vec![target], msg).await.map(|_| ())
    }

    pub async fn dial(&self, target: String, number: String) -> Result<(), TandemError> {
        self.send(vec![target], crate::proto::Msg::Dial { number }).await.map(|_| ())
    }

    pub async fn ring(&self, target: String, on: bool) -> Result<(), TandemError> {
        self.send(vec![target], crate::proto::Msg::Ring { on }).await.map(|_| ())
    }

    pub async fn send_input(&self, target: String, input: TandemInput) -> Result<(), TandemError> {
        self.send(vec![target], crate::proto::Msg::Input(input.into())).await.map(|_| ())
    }

    pub async fn send_hotspot(&self, target: String, hotspot: TandemHotspot) -> Result<(), TandemError> {
        self.send(vec![target], crate::proto::Msg::Hotspot(hotspot.into())).await.map(|_| ())
    }

    pub async fn decline_offer(&self, from: String, offer: u64) -> Result<(), TandemError> {
        let from = DeviceId::parse(&from)?;
        let engine = self.engine.clone();
        self.runtime.spawn(async move { engine.decline_offer(from, offer).await }).await.map_err(join_error)?;
        Ok(())
    }

    pub async fn shutdown(&self) {
        let engine = self.engine.clone();
        let _ = self.runtime.spawn(async move { engine.shutdown().await }).await;
    }
}

impl TandemEngine {
    async fn send(&self, targets: Vec<String>, msg: crate::proto::Msg) -> Result<Vec<String>, TandemError> {
        let targets = parse_ids(&targets)?;
        let wanted = targets.len();
        let engine = self.engine.clone();
        let reached = self
            .runtime
            .spawn(async move { engine.send_msg(&targets, msg).await })
            .await
            .map_err(join_error)?;
        if reached.is_empty() && wanted > 0 {
            return Err(TandemError::NotConnected);
        }
        Ok(ids_to_strings(reached))
    }
}

fn join_error(e: tokio::task::JoinError) -> TandemError {
    TandemError::Failed { reason: format!("internal error: {e}") }
}
